#include <list>
#include <iostream>

int main() {
    std::list<int> safe_list = {10};
    std::list<int> empty_list;

    // Safe access
    if (!safe_list.empty()) {
        std::cout << safe_list.front() << "\n"; // OK
    }

    // UNSAFE: Undefined Behavior
    // std::cout << empty_list.front() << "\n"; 

    // Safe check for empty access
    if (empty_list.empty()) {
        std::cerr << "Error: List is empty.\n";
    }
}
